async function generateChatResponse(message, context = {}) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'generateChatResponse',
        message: message,
        context: context
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to generate chat response');
    }

    return {
      success: true,
      response: result.response,
      originalMessage: message,
      contextUsed: context,
      message: `Generated AI response for: '${message.substring(0, 50)}${message.length > 50 ? '...' : ''}'`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
